mapper.sql:
WHERE services.is_active = 1

    AND services.company_id = #{filter.companyId}


    AND services.section_id = #{filter.sectionId}


    AND services.name LIKE CONCAT("%", #{filter.searchText}, "%")

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        services.`name` ASC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM services
WHERE is_active = 1 AND name = #{name}
 AND id != #{id}
